package com.metaverse.coin.strategy.job.funding.config;
import com.metaverse.coin.strategy.core.arbitrage.multi.*; import com.metaverse.coin.strategy.core.arbitrage.config.MultiExchangeFundingRateProperties; import org.junit.jupiter.api.Test; import org.springframework.boot.test.context.runner.ApplicationContextRunner; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.mock;
class CrossExchangePaperConfigurationTest {
 private final ApplicationContextRunner runner=new ApplicationContextRunner().withUserConfiguration(CrossExchangePaperConfiguration.class,MultiExchangeFundingRateProperties.class,BinanceFundingRateGateway.class,OkxFundingRateGateway.class,HtxFundingRateGateway.class,BitgetFundingRateGateway.class,HyperliquidFundingRateGateway.class).withBean(CrossExchangeArbitragePersistenceService.class,()->mock(CrossExchangeArbitragePersistenceService.class)).withPropertyValues("arbitrage.multi-exchange.min-net-yield-rate=0.0003","arbitrage.multi-exchange.minimum-horizon-net-yield=0.0001","arbitrage.multi-exchange.expected-holding-windows=2","arbitrage.multi-exchange.costs.binance.taker-fee-rate=0.0004");
 @Test void startsInPaperModeWithFivePublicOnlyProviders(){runner.run(ctx->{assertThat(ctx).hasNotFailed();assertThat(ctx.getBeansOfType(CrossExchangeMarketDataProvider.class)).hasSize(5);assertThat(ctx).hasSingleBean(CrossExchangePaperTradingService.class);assertThat(ctx).hasSingleBean(CrossExchangeOpportunityScanService.class);});}
}
